import openpyxl,re
wb = openpyxl.load_workbook('documents/construction-budget-draw-schedule.xlsx', data_only=True)
def num(v):
    if isinstance(v,(int,float)): return v
    if isinstance(v,str):
        s=v.replace('\$','').replace(',','').replace('(','-').replace(')','').strip()
        try: return float(s)
        except: return None
    return None
ws=wb['Detailed Budget']
cols={5:'Total',6:'Senior',7:'Mezz',8:'Equity',9:'Retainage',10:'NetDisb'}
sums={k:0 for k in cols}
for r in range(6, ws.max_row+1):
    a=ws.cell(r,1).value
    if isinstance(a,str) and re.match(r'^\d\.\d\d',a.strip()):
        for c in cols:
            v=num(ws.cell(r,c).value)
            if v: sums[c]+=v
for c in cols: print(cols[c], f'{sums[c]:,.0f}')
print()
print('Stated Net Disbursable (grand total):', ws.cell(46,10).value if ws.cell(46,10).value else '')
# find grand total row
for r in range(40,50):
    lbl=ws.cell(r,3).value
    if lbl and 'GRAND' in str(lbl):
        print('row',r,'grand total row:', [ws.cell(r,c).value for c in cols])
""}

