import openpyxl
wb = openpyxl.load_workbook('documents/construction-budget-draw-schedule.xlsx', data_only=True)
ws=wb['Draw Schedule']
def num(v):
    if isinstance(v,(int,float)): return v
    if isinstance(v,str):
        s=v.replace('\$','').replace(',','').replace('(','-').replace(')','').strip()
        try: return float(s)
        except: return None
    return None
cols={5:'HardGross',6:'Retainage',7:'HardNet',8:'Soft',9:'IR',10:'Fees',11:'DevFee',12:'Conting',13:'TotalDraw'}
sums={k:0.0 for k in cols.values()}
for r in range(5,14):
    rowsum=0
    for c,n in cols.items():
        v=num(ws.cell(r,c).value)
        if v is not None:
            sums[n]+=v
            if c>=7: rowsum+=v
    tot=num(ws.cell(r,13).value)
    print('Draw',ws.cell(r,1).value,'components(7-12)sum=',f'{rowsum:,.0f}','statedTotal=',f'{tot:,.0f}','diff=',f'{rowsum-tot:,.0f}')
print()
for n,v in sums.items(): print(n, f'{v:,.0f}')
print('component total (hard net+soft+IR+fees+devfee+conting):', f\"{sums['HardNet']+sums['Soft']+sums['IR']+sums['Fees']+sums['DevFee']+sums['Conting']:,.0f}\")
print('stated column totals row 14:', [ws.cell(14,c).value for c in cols])
""}

